svg.script:
// Estado de la aplicación
let categoriaSeleccionada = "";
let menuCategoriasVisible = false;

// Elementos DOM
const tituloText = document.getElementById("tituloText");
const categoriaText = document.getElementById("categoriaText");
const ubicacionText = document.getElementById("ubicacionText");
const descripcionText = document.getElementById("descripcionText");
const categoriaMenu = document.getElementById("categoriaMenu");
const dropdownIcon = document.getElementById("dropdownIcon");
const btnEnviar = document.getElementById("btnEnviar");
const statusBox = document.getElementById("statusBox");
const statusMsg = document.getElementById("statusMsg");

// Variables del formulario
let titulo = "";
let ubicacion = "";
let descripcion = "";

// Función para mostrar mensaje de estado
function showStatus(message, isError) {
    statusBox.style.display = "block";
    statusMsg.textContent = message;
    if (isError) {
        statusMsg.setAttribute("fill", "#c62828");
        statusBox.setAttribute("fill", "#ffebee");
    } else {
        statusMsg.setAttribute("fill", "#2e7d32");
        statusBox.setAttribute("fill", "#e8f5e9");
    }

    setTimeout(function() {
        statusBox.style.display = "none";
    }, 3000);
}

// Simular envío a base de datos
function enviarDenuncia() {
    // Obtener valores actuales
    var tituloVal = tituloText.textContent;
    if (tituloVal === "Ej: Corrupción en alcaldía" || tituloVal === "Escriba aquí...") {
        showStatus("❌ Por favor ingrese un título", true);
        return;
    }

    if (!categoriaSeleccionada) {
        showStatus("❌ Por favor seleccione una categoría", true);
        return;
    }

    var ubicacionVal = ubicacionText.textContent;
    if (ubicacionVal === "Ej: Comuna 7, Ibagué" || ubicacionVal === "") {
        showStatus("❌ Por favor ingrese una ubicación", true);
        return;
    }

    var descripcionVal = descripcionText.textContent;
    if (descripcionVal === "Escriba los detalles de la denuncia..." || descripcionVal === "") {
        showStatus("❌ Por favor ingrese una descripción", true);
        return;
    }

    // Simular conexión a base de datos
    showStatus("📡 Conectando a la base de datos...", false);

    // Simular delay de red
    setTimeout(function() {
        showStatus("✅ Denuncia enviada exitosamente a la base de datos", false);

        // Limpiar formulario
        tituloText.textContent = "Ej: Corrupción en alcaldía";
        categoriaText.textContent = "Seleccionar...";
        categoriaSeleccionada = "";
        ubicacionText.textContent = "Ej: Comuna 7, Ibagué";
        descripcionText.textContent = "Escriba los detalles de la denuncia...";

        // Cambiar colores de texto
        tituloText.setAttribute("fill", "#999");
        categoriaText.setAttribute("fill", "#999");
        ubicacionText.setAttribute("fill", "#999");
        descripcionText.setAttribute("fill", "#999");

    }, 1500);
}

// Manejar clic en campos editables
tituloText.addEventListener("click", function() {
    var valorActual = tituloText.textContent;
    var nuevoValor = prompt("Ingrese el título de la denuncia:", 
        valorActual === "Ej: Corrupción en alcaldía" ? "" : valorActual);
    if (nuevoValor && nuevoValor.trim() !== "") {
        tituloText.textContent = nuevoValor.trim();
        tituloText.setAttribute("fill", "#333");
    }
});

ubicacionText.addEventListener("click", function() {
    var valorActual = ubicacionText.textContent;
    var nuevoValor = prompt("Ingrese la ubicación:", 
        valorActual === "Ej: Comuna 7, Ibagué" ? "" : valorActual);
    if (nuevoValor && nuevoValor.trim() !== "") {
        ubicacionText.textContent = nuevoValor.trim();
        ubicacionText.setAttribute("fill", "#333");
    }
});

descripcionText.addEventListener("click", function() {
    var valorActual = descripcionText.textContent;
    var nuevoValor = prompt("Ingrese la descripción detallada:", 
        valorActual === "Escriba los detalles de la denuncia..." ? "" : valorActual);
    if (nuevoValor && nuevoValor.trim() !== "") {
        descripcionText.textContent = nuevoValor.trim();
        descripcionText.setAttribute("fill", "#333");
    }
});

// Dropdown de categorías
function toggleCategoriaMenu() {
    if (menuCategoriasVisible) {
        categoriaMenu.style.display = "none";
    } else {
        categoriaMenu.style.display = "block";
    }
    menuCategoriasVisible = !menuCategoriasVisible;
}

dropdownIcon.addEventListener("click", toggleCategoriaMenu);

// Seleccionar categoría
var catOptions = document.querySelectorAll(".catOption");
for (var i = 0; i < catOptions.length; i++) {
    catOptions[i].addEventListener("click", function() {
        categoriaSeleccionada = this.getAttribute("data-cat");
        categoriaText.textContent = categoriaSeleccionada;
        categoriaText.setAttribute("fill", "#333");
        toggleCategoriaMenu();
    });
}

// Botón enviar
btnEnviar.addEventListener("click", enviarDenuncia);

// Cerrar menú al hacer clic fuera
document.documentElement.addEventListener("click", function(e) {
    if (menuCategoriasVisible && e.target !== dropdownIcon && 
        e.target !== categoriaMenu && !e.target.classList?.contains("catOption")) {
        toggleCategoriaMenu();
    }
});

// Hover effects para denuncias
var denuncias = document.querySelectorAll(".denunciaItem");
for (var i = 0; i < denuncias.length; i++) {
    denuncias[i].addEventListener("mouseenter", function() {
        this.setAttribute("fill", "#fff8e1");
    });
    denuncias[i].addEventListener("mouseleave", function() {
        var originalFill = this.getAttribute("data-original-fill");
        this.setAttribute("fill", originalFill || "white");
    });
    denuncias[i].addEventListener("click", function() {
        showStatus("📋 Detalles de la denuncia cargados (simulado)", false);
    });
    // Guardar color original
    var originalFill = denuncias[i].getAttribute("fill");
    if (originalFill) {
        denuncias[i].setAttribute("data-original-fill", originalFill);
    }
}

// Hover effects para noticias
var noticias = document.querySelectorAll(".noticiaItem");
for (var i = 0; i < noticias.length; i++) {
    noticias[i].addEventListener("mouseenter", function() {
        this.setAttribute("fill", "#f3e5f5");
    });
    noticias[i].addEventListener("mouseleave", function() {
        var originalFill = this.getAttribute("data-original-fill");
        if (originalFill) {
            this.setAttribute("fill", originalFill);
        }
    });
    noticias[i].addEventListener("click", function() {
        showStatus("📖 Abriendo noticia completa (simulado)", false);
    });
    // Guardar color original
    var originalFill = noticias[i].getAttribute("fill");
    if (originalFill) {
        noticias[i].setAttribute("data-original-fill", originalFill);
    }
}

console.log("✅ Sistema El Hormiguero cargado - Modo demostración");
